workflow.set_entry_point('node_0')
workflow.add_edge('node_1', 'node_2')
workflow.add_edge('node_2', 'node_3')
workflow.add_edge('node_3', 'node_4')
workflow.add_edge('node_0', END)
app = workflow.compile()

if __name__ == '__main__':
    print('Starting LangGraph process...')
    result = app.invoke({'input': "Eres un Content Manager B2B. Tu objetivo es generar 5 posts diarios para LinkedIn enfocados en Cloud y Ciberseguridad. Usa tono profesional, ganchos fuertes y CTAs claros. Los resultados deben estructurarse en formato JSON listos para postear."})
